import sys
input = sys.stdin.read

def can_form_array(n, k, a):
    # Convert the array 'a' into its representation in base 'k'
    base_k_counts = {}

    for val in a:
        i = 0
        while val > 0:
            power_count = val % k
            if power_count > 1:
                return False
            if power_count == 1:
                if i in base_k_counts:
                    return False
                base_k_counts[i] = 1
            val //= k
            i += 1

    return True

def main():
    data = input().split()
    index = 0
    T = int(data[index])
    index += 1
    results = []

    for _ in range(T):
        n = int(data[index])
        k = int(data[index + 1])
        index += 2
        a = list(map(int, data[index:index + n]))
        index += n

        if can_form_array(n, k, a):
            results.append("YES")
        else:
            results.append("NO")

    for result in results:
